changeSet.sql:
UPDATE agent_runs SET status = 'FAILED', error = COALESCE(error, 'Interrupted by the agent_sessions migration'), updated_at = CURRENT_TIMESTAMP WHERE session_id IS NULL AND status IN ('ENQUEUED', 'RUNNING');
INSERT INTO agent_sessions (scope, agent_id, user_id, connector_code, connection_id, title, last_activity_at, closed_at, created_at, updated_at) SELECT DISTINCT ON (r.agent_id, tl.connection_id) 'CONNECTION', r.agent_id, tl.user_id, tl.connector_code, tl.connection_id::uuid, 'Runs before the session migration', MAX(r.created_at) OVER (PARTITION BY r.agent_id, tl.connection_id), CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM agent_runs r JOIN trigger_logs tl ON tl.id = r.trigger_log_id WHERE r.session_id IS NULL;
UPDATE agent_runs r SET session_id = s.id, updated_at = CURRENT_TIMESTAMP FROM trigger_logs tl, agent_sessions s WHERE tl.id = r.trigger_log_id AND r.session_id IS NULL AND s.scope = 'CONNECTION' AND s.closed_at IS NOT NULL AND s.agent_id = r.agent_id AND s.connection_id = tl.connection_id::uuid;
